"""Regenerates pyvalues_test.go: the expected values of the rt tests, computed by
Python (the reference). Run from lattice/gogen/rt:

    uv run python testdata/gen_pyvalues.py > pyvalues_test.go && gofmt -w pyvalues_test.go
"""

import json
import math
import sys


def go_str(s: str) -> str:
    """A Go string literal for s (json escapes are valid Go escapes for BMP text; astral
    characters are written as \\U escapes)."""
    out = []
    for ch in s:
        c = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif c < 0x20 or c == 0x7F:
            out.append("\\x%02x" % c)
        elif c < 0x7F:
            out.append(ch)
        elif 0xD800 <= c <= 0xDFFF:
            raise ValueError("surrogate")
        elif c > 0xFFFF:
            out.append("\\U%08x" % c)
        else:
            out.append("\\u%04x" % c)
    return '"' + "".join(out) + '"'


def go_float(v: float) -> str:
    if math.isnan(v):
        return "math.NaN()"
    if math.isinf(v):
        return "math.Inf(1)" if v > 0 else "math.Inf(-1)"
    if v == 0 and math.copysign(1, v) < 0:
        return "math.Copysign(0, -1)"
    return repr(v)


def outcome(f) -> str:
    try:
        return f()
    except Exception as e:  # noqa: BLE001 - recorded as "!Kind: message"
        return f"!{type(e).__name__}: {e}"


w = sys.stdout.write
w("// Code generated by testdata/gen_pyvalues.py from Python %s; DO NOT EDIT.\n\n" % sys.version.split()[0])
w("package rt\n\nimport \"math\"\n\n")

# ---- float format specs -----------------------------------------------------------------
vals = [0.0, -0.0, 1.0, -1.5, 2.5, 0.125, 1234567.891, 1e16, 1e-5, 123456789.0, 1e300, 5e-324,
        float("inf"), float("-inf"), float("nan"), 0.1 + 0.2, 99.995, 1e22, 0.5, 12345.6789,
        0.000123456789, 12345678.123456789, -0.001, 0.3]
specs = ["", ".2f", "f", ".0f", "e", ".3e", "E", "g", ".3g", "G", ".0g", "#.3g", "%", ".1%",
         ",", ",.2f", "_.3f", "10", "<10", "^10.2f", "*>12,.1f", "+", " ", "+.2e", "010.2f",
         "=+10.1f", "z.1f", "08", "#", ".3", ".10", ",g", "010", "0<8", "-^9.1f", "#.0f", "#e",
         ".12g", ".17g", "n", "12.4G", "#.0e", "F", ".3F", "012,.1f", "0=12,.1f", "12,.1f",
         "010,", "=10", "0>10", ".6,f", ",.6_f", ".7_e", ".8,g", ".7,", ".8,%", "015.6,f",
         "0=15.6_f", ".0,f", "#.0,f", ".6,", ".,f", "#10", ".6_E", "+z010.3f", "x<010.2f",
         "é^9", "10.2%", "#g", "#.0g", "#,.0f", ",.0f", "_", "020_", ".1e", ".0e", ".0%", "#.0%",
         ".16g", ".20f", ".25e", "z", "z.0f", "-", "-10", " 010.1f", "^", ">",
         # invalid specs
         "x", ",,", ",_", ".3,n", ",n", "0z", " 0=10.1f", "{", ".2d", "%10", "1_000", ".", "10.",
         ".f", "++", "#z"]
w("var formatFloatCases = []struct {\n\tv    float64\n\tspec string\n\twant string\n}{\n")
for v in vals:
    for s in specs:
        w("\t{%s, %s, %s},\n" % (go_float(v), go_str(s), go_str(outcome(lambda: format(v, s)))))
